// cat: 1 weapon, 2 ammo, 3 recovery, 4 treasure, 5 key item, 6 armor and the like.
// kind (weapons): 1 firearm, 2 knife or melee, 3 thrown, 7 lantern. magazine: a
// magazine-fed firearm (its count is the rounds loaded).
// offer: an Add list offers it - what the story gives Chris and Sheva to carry: the
// shop's price list's items and the weapons its "every kind of weapon" achievement
// counts (the launcher's loads). The rest are named for what the game holds: each
// character's knife, the Mercenaries' guns, the scene-only weapons, the floor herbs.
// only: the one character Item Management lets take it (its own check), or nullptr.
struct Info {
  uint16_t id;
  uint8_t cat;
  uint8_t kind;
  bool magazine;
  bool offer;
  int32_t num;   // the count it comes with
  int32_t most;  // the record's most (0: none)
  const char* only;
  const char* name;
};

